<div class="page-heading"><div><a class="back-link" href="<?=e(route_url('edit',['id'=>$a['id']]))?>">← Back to editor</a><h1>Revision history</h1><p><?=e($a['title'])?> · Restoring loads an earlier version into the draft.</p></div></div>
<div class="history-list"><?php foreach($history as $r): ?><section class="history-card"><div><h2><?=e($r['title'])?></h2><p>Published <?=e(formatted_date($r['created_at']))?> by <?=e($r['editor'])?> · Revision #<?=$r['id']?> <?php if((int)$a['published_revision_id']===(int)$r['id']): ?><span class="badge published">Current</span><?php endif; ?></p><details><summary>Read this revision</summary><div class="article-body"><?=$r['html']?></div></details></div><form method="post" action="<?=e(route_url('history',['id'=>$a['id']]))?>" data-confirm="Replace the working draft with this revision? The published version will stay unchanged."><?=csrf_field()?><input type="hidden" name="version" value="<?=$a['lock_version']?>"><input type="hidden" name="revision" value="<?=$r['id']?>"><button class="button secondary small" type="submit">Restore to draft</button></form></section><?php endforeach; ?><?php if(!$history): ?><div class="empty-state"><h2>No published revisions yet</h2><p>A revision is saved each time you publish.</p></div><?php endif; ?></div>
